import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.Dj7FWXx_.js";const p=JSON.parse('{"title":"原生 LinuxQQ 协议证据表","description":"","frontmatter":{},"headers":[],"relativePath":"reference/linuxqq-native-evidence.md","filePath":"reference/linuxqq-native-evidence.md","lastUpdated":null}'),r={name:"reference/linuxqq-native-evidence.md"};function a(i,t,n,l,h,s){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="原生-linuxqq-协议证据表" tabindex="-1">原生 LinuxQQ 协议证据表 <a class="header-anchor" href="#原生-linuxqq-协议证据表" aria-label="Permalink to &quot;原生 LinuxQQ 协议证据表&quot;">​</a></h1><p>本文只记录可观察行为、脱敏字段形状和独立实现的验证入口，不包含腾讯源码、账号票据、二维码签名、设备秘密、PCAP 或反编译工程。</p><h2 id="基线" tabindex="-1">基线 <a class="header-anchor" href="#基线" aria-label="Permalink to &quot;基线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>固定值</th><th>证据</th></tr></thead><tbody><tr><td>检查日期</td><td>2026-08-28</td><td>实施开始时重新读取 QQ 官方 <code>pcConfig.json</code></td></tr><tr><td>LinuxQQ</td><td><code>3.2.32-51802</code>，amd64</td><td>官方配置和 DEB 包元数据</td></tr><tr><td>DEB 大小</td><td><code>184998970</code> bytes</td><td>下载后本地只读校验</td></tr><tr><td>DEB SHA-256</td><td><code>81AE2B8542EF5311FC72ECF53C9A523923C834569C7B0DA52E0BF4360B9CB5F9</code></td><td>下载后本地只读校验</td></tr><tr><td>QUA / package sign</td><td><code>V1_LNX_NQ_3.2.32_51802_GW_B</code></td><td>官方包静态字符串及调用点交叉引用</td></tr></tbody></table><p>官方安装包、解包内容、反编译结果、抓包和分析工程位于源码树外的研究目录，不由 Go embed、前端构建或发布脚本引用。</p><h2 id="linuxqq-登录调用与帧" tabindex="-1">LinuxQQ 登录调用与帧 <a class="header-anchor" href="#linuxqq-登录调用与帧" aria-label="Permalink to &quot;LinuxQQ 登录调用与帧&quot;">​</a></h2><table tabindex="0"><thead><tr><th>符号或调用点</th><th>请求命令/行为</th><th>字段和常量</th><th>加密层</th><th>证据与独立实现</th></tr></thead><tbody><tr><td><code>getQRCodePicture</code></td><td><code>wtlogin.trans_emp</code>，Code2D <code>0x31</code> 获取二维码</td><td>SSO <code>app_id=537376854</code>、<code>magic=2052</code>；主登录 AppID <code>1600001615</code>；shell AppID <code>537376650</code></td><td>匿名 PC Code2D ECDH + TEA</td><td>官方客户端离线调用图、脱敏 PCAP SSO 头和 <code>TestNativeLinuxQQCode2DFrameMatchesOfficialAnonymousEnvelope</code></td></tr><tr><td><code>startPolling</code></td><td><code>wtlogin.trans_emp</code>，Code2D <code>0x31</code> 轮询</td><td>本次 attempt 的 QR signature；状态只允许等待扫描、等待确认、成功、过期或取消</td><td>与获取二维码相同的 ECDH 会话</td><td>静态调用图、响应分支和二维码状态测试</td></tr><tr><td><code>abortPolling</code></td><td>取消当前 attempt 并销毁 QR 上下文</td><td>attempt ID、创建时间、QR signature 只驻留内存</td><td>不复用旧 ECDH/QR 密钥</td><td>状态机测试；取消不得清除上一份仍有效的缓存票据</td></tr><tr><td><code>quickLoginWithUin</code></td><td>本地票据恢复后调用 <code>StatusService.Register</code></td><td>UIN、UID、T10A/会话票据、独立 Linux 设备资料</td><td>已登录 SSO 封装</td><td>静态调用图、登录头测试和缓存成功/失败测试</td></tr><tr><td><code>setAutoLogin</code></td><td>设置本地登录策略</td><td><code>auto</code> 或 <code>qr</code>；旧 <code>quick</code>/<code>ticket</code> 只作为 <code>auto</code> 输入别名</td><td>无独立网络请求</td><td>账号存储和登录管理器契约测试</td></tr><tr><td><code>getLoginList</code></td><td>枚举本地 LinuxQQ 登录记录</td><td><code>(self_id, client_type=linuxqq)</code>；不读取安卓实例作为同一运行对象</td><td>无</td><td>双协议运行时测试</td></tr><tr><td><code>resetLoginInfo</code></td><td>清理确定失效的 LinuxQQ 会话</td><td>仅 LinuxQQ token/uid/nickname 会话字段</td><td>无</td><td>协议隔离与缓存持久化测试</td></tr><tr><td><code>deleteLoginInfo</code></td><td>删除 LinuxQQ 本地账号记录</td><td>不删除同 QQ 安卓账号或票据</td><td>无</td><td>CRUD 与协议隔离测试</td></tr><tr><td>注册调用点</td><td><code>StatusService.Register</code></td><td>LinuxQQ QUA、GUID、UID/UIN、在线状态</td><td>已登录 SSO 封装</td><td>静态调用图；LinuxQQ 重连分支测试</td></tr><tr><td>心跳调用点</td><td>LinuxQQ 注册结果驱动的连接心跳</td><td>心跳周期由 MSF 运行时维护，不硬编码为等级任务计时器</td><td>已登录 SSO 封装</td><td>运行时状态和重连测试</td></tr></tbody></table><p><code>537376854</code> 不是从安装包元数据猜测的值：当前基线的脱敏 PCAP 中，<code>wtlogin.trans_emp</code> 外层 SSO 头同时出现 <code>app_id=537376854</code> 和 <code>magic=2052</code>。常量变化时必须同时更新抓包证据和 golden test，禁止只改常量让测试通过。</p><h2 id="reserve" tabindex="-1">Reserve <a class="header-anchor" href="#reserve" aria-label="Permalink to &quot;Reserve&quot;">​</a></h2><table tabindex="0"><thead><tr><th>protobuf 字段</th><th>内容</th><th>证据等级</th></tr></thead><tbody><tr><td><code>12</code></td><td>小写设备 GUID</td><td>官方帧与静态调用点交叉确认</td></tr><tr><td><code>13</code></td><td>单字节 <code>0</code></td><td>官方帧</td></tr><tr><td><code>15</code></td><td>W3C <code>traceparent</code> 形状，随机 trace/span ID</td><td>官方帧形状；每次请求重新生成</td></tr><tr><td><code>23</code></td><td><code>client_conn_seq</code> 子消息</td><td>官方帧与调用点</td></tr><tr><td><code>24</code></td><td>客户端信息；包含 32-byte 随机值和 QUA</td><td>官方帧与静态字符串</td></tr><tr><td><code>26</code></td><td><code>101</code></td><td>官方帧</td></tr></tbody></table><p>实现位于 <code>internal/sso/linuxqq.reserve.go</code>。随机字段的 golden test 只校验结构、长度和固定字段，不固化真实随机数。</p><h2 id="安卓协议自动授权" tabindex="-1">安卓协议自动授权 <a class="header-anchor" href="#安卓协议自动授权" aria-label="Permalink to &quot;安卓协议自动授权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>命令</th><th>绑定条件</th><th>加密层</th><th>证据与测试</th></tr></thead><tbody><tr><td>识别/检查</td><td><code>wtlogin.qrlogin</code> / <code>0x13</code></td><td>同一 QQ、在线安卓实例、本次未过期 Code2D <code>qrSig</code></td><td>Code2D 层使用 STKey TEA；外层使用 WTSessionTicketKey TEA</td><td>官方安卓 QQ 9.2.70 离线控制流；<code>TestWTLoginAndroidQRCodeOperationsUseBoundTicketLayers</code></td></tr><tr><td>同意授权</td><td><code>wtlogin.qrlogin</code> / <code>0x14</code></td><td>在上述条件上要求 A1、A2、NoPicSig、ST 等完整有效票据</td><td>同上</td><td>官方安卓离线控制流及双层解密结构测试</td></tr><tr><td>取消/拒绝</td><td><code>wtlogin.qrlogin</code> / <code>0x16</code></td><td>只允许取消本次 attempt，不接受旧 <code>qrSig</code></td><td>同上</td><td>官方安卓离线控制流及 operation golden test</td></tr></tbody></table><p>官方 3.2.32 实网响应中，二维码 URL 的可打印 <code>k</code> 参数与 Code2D 二进制 <code>qrSig</code> 并不相同；Android 的扫描和授权请求使用后者。匿名官方网络冒烟会同时确认 URL <code>k</code> 存在和本次会话 <code>qrSig</code> 已绑定，单元测试保证自动授权不会误用 URL 文本。</p><p>任何票据、二维码授权密钥、设备秘密和完整响应体都不得写入日志、API、事件或本文档。实机差分只允许记录状态码、字段是否存在、长度和状态迁移。</p><h2 id="负向审计" tabindex="-1">负向审计 <a class="header-anchor" href="#负向审计" aria-label="Permalink to &quot;负向审计&quot;">​</a></h2><p>原生 LinuxQQ 运行链不得引用 <code>desktopqq</code>、Docker 桌面容器、Linux 桌面窗口、Electron 控制、截图识别、键鼠模拟或固定 GUI 流程。小米 8 Hook 仅用于脱敏验收与抓包诊断，不是框架运行时依赖；其中已有的 UI 扫码/点击辅助入口不得接入本实现。</p>',17)])])}const Q=d(r,[["render",a]]);export{p as __pageData,Q as default};
